    width: 32,
    height: 32,
    callback: function (x, y, level) {
      const width = 32;
      const height = 32;
      const heights = new Float32Array(width * height);
      const tiles = 1 << level;
      for (let row = 0; row < height; row++) {
        for (let col = 0; col < width; col++) {
          const u = (x + col / (width - 1)) / tiles;
          const v = (y + row / (height - 1)) / tiles;
          const lon = u * 360.0 - 180.0;
          const lat = 90.0 - v * 180.0;
          const dLon = lon + 112.14;
          const dLat = lat - 36.08;
          const local = Math.exp(-(dLon * dLon) / 1.4 - (dLat * dLat) / 0.32);
          const trench = -4200.0 * Math.exp(-Math.pow((dLat + Math.sin(dLon * 5.0) * 0.04) / 0.06, 2.0)) * local;
          const rims = 2100.0 * Math.exp(-Math.pow((Math.abs(dLat) - 0.15) / 0.08, 2.0)) * local;
          const ridges = (
            Math.sin((lon + 112.0) * 38.0) * 650.0 +
            Math.cos((lat - 36.0) * 54.0) * 520.0
          ) * local;
          heights[row * width + col] = 2200.0 + rims + ridges + trench;
        }
      }
      return heights;
    },
  }),
}));

